library(shiny)
library(bslib)
library(ggplot2)

# ==============================================================================
# 1. GENERATE REPRODUCIBLE DATASETS ON STARTUP
# ==============================================================================
set.seed(2026)

# Question 1: Poisson(lambda = 3.2), N = 400
data_pois <- rpois(400, lambda = 3.2)

# Question 2 (Mystery Dataset A): Exponential(lambda = 0.4), n = 200
data_qq_1 <- rexp(200, rate = 0.4)

# Question 3 (Mystery Dataset B): Normal(mu = 50, sigma^2 = 36), n = 200
data_qq_2 <- rnorm(200, mean = 50, sd = sqrt(36))

# Question 4 (Mystery Dataset C): Uniform(a = 10, b = 30), n = 200
data_qq_3 <- runif(200, min = 10, max = 30)


# ==============================================================================
# 2. UI HELPER: SLIDER PAIRED WITH NUMERIC INPUT BOX
# ==============================================================================
sliderAndBoxUI <- function(ns, id, label_html, min, max, value, step) {
  div(
    class = "mb-3",
    tags$label(class = "form-label fw-semibold mb-1", HTML(label_html)),
    div(
      class = "d-flex align-items-center gap-2",
      div(
        style = "flex: 1;",
        sliderInput(ns(id), label = NULL, min = min, max = max, value = value, step = step, width = "100%")
      ),
      div(
        style = "width: 95px; margin-bottom: 15px;",
        numericInput(ns(paste0(id, "_num")), label = NULL, value = value, min = min, max = max, step = step, width = "100%")
      )
    )
  )
}

# Helper for two-way syncing between a slider and its numeric input box
registerSyncPair <- function(input, session, slider_id, step_val) {
  num_id <- paste0(slider_id, "_num")
  
  observeEvent(input[[slider_id]], {
    s_val <- input[[slider_id]]
    n_val <- input[[num_id]]
    if (is.na(n_val) || abs(s_val - n_val) > (step_val / 2 + 1e-9)) {
      updateNumericInput(session, num_id, value = s_val)
    }
  }, ignoreInit = TRUE)
  
  observeEvent(input[[num_id]], {
    n_val <- input[[num_id]]
    s_val <- input[[slider_id]]
    if (!is.null(n_val) && !is.na(n_val) && !isTRUE(all.equal(as.numeric(n_val), as.numeric(s_val)))) {
      updateSliderInput(session, slider_id, value = n_val)
    }
  }, ignoreInit = TRUE)
}

getSyncedParam <- function(input, slider_id) {
  n_val <- input[[paste0(slider_id, "_num")]]
  if (!is.null(n_val) && !is.na(n_val)) return(as.numeric(n_val))
  as.numeric(input[[slider_id]])
}


# ==============================================================================
# 3. MODULE FOR TAB 1: POISSON-NESS PLOT (PROPORTIONS)
# ==============================================================================
poissonTabUI <- function(id) {
  ns <- NS(id)
  
  nav_panel(
    title = "Question 1: Poisson-ness Plot",
    layout_sidebar(
      sidebar = sidebar(
        width = 390,
        h5("1. Inspect the Poisson-ness Plot"),
        p(
          class = "text-muted small",
          HTML("For observed counts <i>k = 0, 1, 2, &hellip;</i> the vertical axis plots <b>ln(n<sub>k</sub>) - ln(N) + ln(<i>k</i>!)</b> against <i>k</i>.")
        ),
        hr(),
        h5("2. Fit a Line to Estimate λ"),
        checkboxInput(ns("show_line"), "Show Manual Fitted Line (y = a + bk)", value = TRUE),
        sliderAndBoxUI(ns, "intercept", "Intercept (a):", min = -8.0, max = 2.0, value = -1.5, step = 0.05),
        sliderAndBoxUI(ns, "slope", "Slope (b):", min = -1.0, max = 3.0, value = 0.5, step = 0.02),
        div(
          class = "alert alert-light border small mt-2 mb-0",
          tags$strong("How the Line Controls Work:"),
          tags$ul(
            class = "mb-0 ps-3 mt-1",
            tags$li(HTML("<b>Intercept (<i>b</i><sub>0</sub>):</b> Vertical value of the line at <i>k</i> = 0. Shifts the entire line up or down.")),
            tags$li(HTML("<b>Slope (<i>b</i><sub>1</sub>):</b> Change in vertical axis per 1-unit increase in <i>k</i>. Tilts the steepness of the line."))
          )
        ),
        hr(),
        downloadButton(ns("dl_pois"), "Download Count Data (.csv)", class = "btn-sm btn-outline-primary w-100")
      ),
      layout_columns(
        col_widths = c(7, 5),
        card(
          card_header("Poisson-ness Plot"),
          plotOutput(ns("pois_plot"), height = "480px")
        ),
        card(
          card_header(sprintf("Observed Counts Table (Sample Size N = %d)", length(data_pois))),
          tableOutput(ns("freq_table"))
        )
      )
    )
  )
}

poissonTabServer <- function(id, dataset) {
  moduleServer(id, function(input, output, session) {
    registerSyncPair(input, session, "intercept", 0.05)
    registerSyncPair(input, session, "slope", 0.02)
    
    pois_df <- reactive({
      N <- length(dataset)
      tab <- table(dataset)
      k_vals <- as.numeric(names(tab))
      n_k <- as.numeric(tab)
      p_k <- n_k / N
      
      # lfactorial(k) computes ln(k!) accurately
      metameter <- lfactorial(k_vals) + log(p_k)
      
      data.frame(
        k = k_vals,
        n_k = n_k,
        metameter = metameter
      )
    })
    
    output$pois_plot <- renderPlot({
      df <- pois_df()
      b0 <- getSyncedParam(input, "intercept")
      b1 <- getSyncedParam(input, "slope")
      
      p <- ggplot(df, aes(x = k, y = metameter)) +
        geom_point(size = 3.8, color = "#232D4B") +
        scale_x_continuous(breaks = df$k) +
        labs(
          x = "Observed Count (k)",
          y = "ln(n_k) - ln(N) + ln(k!)",
          title = "Poisson-ness Plot of Observed Counts",
          subtitle = if (input$show_line) {
            sprintf("Manual Line: y = %.2f + %.2f * k", b0, b1)
          } else {
            "Toggle the manual line in the sidebar to fit slope and intercept"
          }
        ) +
        theme_minimal(base_size = 14) +
        theme(
          plot.title = element_text(face = "bold"),
          panel.grid.minor = element_blank()
        )
      
      if (input$show_line) {
        p <- p + geom_abline(
          intercept = b0,
          slope = b1,
          color = "#E57200",
          linetype = 'dashed',
          linewidth = 1.3
        )
      }
      p
    })
    
    output$freq_table <- renderTable({
      df <- pois_df()
      data.frame(
        `Count (k)` = sprintf("%d", df$k),
        `Frequency (n_k)` = sprintf("%d", df$n_k),
        `ln(n_k) - ln(N) + ln(k!)` = sprintf("%.4f", df$metameter),
        check.names = FALSE
      )
    }, width = "100%")
    
    output$dl_pois <- downloadHandler(
      filename = function() { "question1_poisson_data.csv" },
      content = function(file) { write.csv(data.frame(x = dataset), file, row.names = FALSE) }
    )
  })
}


# ==============================================================================
# 4. MODULE FOR TABS 2-4: CONTINUOUS MYSTERY Q-Q PLOTS (NO SUMMARY STATS)
# ==============================================================================
qqMysteryTabUI <- function(id, tab_title, init_dist,
                           u_min_rng, u_max_rng, u_init, u_step,
                           n_mu_rng, n_mu_init, n_mu_step,
                           n_var_rng, n_var_init, n_var_step,
                           e_rate_rng, e_rate_init, e_rate_step) {
  ns <- NS(id)
  
  nav_panel(
    title = tab_title,
    layout_sidebar(
      sidebar = sidebar(
        width = 390,
        
        # Step 1: Select Candidate Family
        h5("1. Select Candidate Distribution"),
        p(class = "text-muted small mb-2", "Switch between distribution families to determine which one makes the Q-Q plot follow a straight line."),
        selectInput(
          ns("dist"),
          "Candidate Distribution Family:",
          choices = c(
            "Uniform (a, b)"   = "unif",
            "Normal (μ, σ²)"   = "norm",
            "Exponential (λ)"  = "exp"
          ),
          selected = init_dist
        ),
        
        hr(),
        # Step 2: Toggle y = x Line & Tune Parameters
        h5("2. Reference Line & Parameter Tuning"),
        checkboxInput(
          ns("show_yx"),
          HTML("<b>Show <i>y = x</i> Reference Line</b>"),
          value = FALSE
        ),
        p(class = "text-muted small mb-2", "Once you identify the linear family, check the box above to display the y = x line and adjust the parameters until the Q-Q points fall directly along y = x."),
        
        # --- UNIFORM CONTROLS ---
        conditionalPanel(
          condition = sprintf("input['%s'] == 'unif'", ns("dist")),
          sliderAndBoxUI(ns, "unif_min", "Minimum (a):", min = u_min_rng[1], max = u_min_rng[2], value = u_init[1], step = u_step),
          sliderAndBoxUI(ns, "unif_max", "Maximum (b):", min = u_max_rng[1], max = u_max_rng[2], value = u_init[2], step = u_step),
          div(
            class = "alert alert-light border small mt-2 mb-0",
            tags$strong("Parameter Interpretation (Uniform):"),
            tags$ul(
              class = "mb-0 ps-3 mt-1",
              tags$li(HTML("<b>Support:</b> Bounded interval [<i>a</i>, <i>b</i>].")),
              tags$li(HTML("<b>Minimum (<i>a</i>) & Maximum (<i>b</i>):</b> Lower and upper endpoints of the theoretical quantiles on the horizontal axis."))
            )
          )
        ),
        
        # --- NORMAL CONTROLS ---
        conditionalPanel(
          condition = sprintf("input['%s'] == 'norm'", ns("dist")),
          sliderAndBoxUI(ns, "norm_mean", "Mean (&mu;):", min = n_mu_rng[1], max = n_mu_rng[2], value = n_mu_init, step = n_mu_step),
          sliderAndBoxUI(ns, "norm_var", "Variance (&sigma;<sup>2</sup>):", min = n_var_rng[1], max = n_var_rng[2], value = n_var_init, step = n_var_step),
          div(
            class = "alert alert-light border small mt-2 mb-0",
            tags$strong("Parameter Interpretation (Normal):"),
            tags$ul(
              class = "mb-0 ps-3 mt-1",
              tags$li(HTML("<b>Support:</b> (&minus;&infin;, &infin;) &mdash; symmetric bell curve.")),
              tags$li(HTML("<b>Mean (&mu;):</b> Location parameter. Shifting &mu; slides the theoretical quantiles horizontally left or right.")),
              tags$li(HTML("<b>Variance (&sigma;<sup>2</sup>):</b> Spread parameter. Increasing &sigma;<sup>2</sup> stretches the theoretical quantiles horizontally (changing the slope of the Q-Q plot)."))
            )
          )
        ),
        
        # --- EXPONENTIAL CONTROLS ---
        conditionalPanel(
          condition = sprintf("input['%s'] == 'exp'", ns("dist")),
          sliderAndBoxUI(ns, "exp_rate", "Rate (&lambda;):", min = e_rate_rng[1], max = e_rate_rng[2], value = e_rate_init, step = e_rate_step),
          div(
            class = "alert alert-light border small mt-2 mb-0",
            tags$strong("Parameter Interpretation (Exponential):"),
            tags$ul(
              class = "mb-0 ps-3 mt-1",
              tags$li(HTML("<b>Support:</b> [0, &infin;) &mdash; right-skewed waiting times anchored at 0.")),
              tags$li(HTML("<b>Rate (&lambda;):</b> Controls the scale of theoretical quantiles. Increasing &lambda; compresses theoretical quantiles toward 0; decreasing &lambda; stretches them toward larger values."))
            )
          )
        ),
        
        hr(),
        downloadButton(ns("dl_qq"), "Download Dataset (.csv)", class = "btn-sm btn-outline-primary w-100")
      ),
      
      # Main Panel Output: Full-Width Q-Q Plot Only
      card(
        card_header("Quantile-Quantile (Q-Q) Plot"),
        plotOutput(ns("qq_plot"), height = "500px")
      )
    )
  )
}

qqMysteryTabServer <- function(id, dataset, u_step, n_mu_step, n_var_step, e_rate_step, file_label) {
  moduleServer(id, function(input, output, session) {
    
    # Sync all slider-box pairs
    registerSyncPair(input, session, "unif_min",  u_step)
    registerSyncPair(input, session, "unif_max",  u_step)
    registerSyncPair(input, session, "norm_mean", n_mu_step)
    registerSyncPair(input, session, "norm_var",  n_var_step)
    registerSyncPair(input, session, "exp_rate",  e_rate_step)
    
    qq_data <- reactive({
      dist <- input$dist
      n <- length(dataset)
      p_grid <- ppoints(n) # (1:n - 0.5) / n
      sample_q <- sort(dataset)
      
      if (dist == "unif") {
        u_min <- getSyncedParam(input, "unif_min")
        u_max <- getSyncedParam(input, "unif_max")
        validate(need(u_min < u_max, "For Uniform(a, b), Minimum (a) must be strictly less than Maximum (b)."))
        theo_q <- qunif(p_grid, min = u_min, max = u_max)
        label_str <- sprintf("Uniform(a = %g, b = %g)", u_min, u_max)
        
      } else if (dist == "norm") {
        mu <- getSyncedParam(input, "norm_mean")
        var_val <- getSyncedParam(input, "norm_var")
        validate(need(var_val > 0, "Variance (σ²) must be strictly positive."))
        theo_q <- qnorm(p_grid, mean = mu, sd = sqrt(var_val))
        label_str <- sprintf("Normal(μ = %g, σ² = %g)", mu, var_val)
        
      } else if (dist == "exp") {
        rate <- getSyncedParam(input, "exp_rate")
        validate(need(rate > 0, "Rate (λ) must be strictly positive."))
        theo_q <- qexp(p_grid, rate = rate)
        label_str <- sprintf("Exponential(λ = %g)", rate)
      }
      
      list(
        df = data.frame(theo_q = theo_q, sample_q = sample_q),
        label_str = label_str
      )
    })
    
    output$qq_plot <- renderPlot({
      info <- qq_data()
      df <- info$df
      
      p <- ggplot(df, aes(x = theo_q, y = sample_q)) +
        geom_point(size = 2.8, alpha = 0.78, color = "#232D4B") +
        labs(
          x = paste("Theoretical Quantiles —", info$label_str),
          y = "Sample (Empirical) Quantiles",
          title = paste("Q-Q Plot:", info$label_str),
          subtitle = if (input$show_yx) {
            "Dashed Orange Line: y = x (Adjust parameters until the Q-Q points lie along this line)"
          } else {
            "Inspect point linearity first, then check 'Show y = x Reference Line' to tune parameters"
          }
        ) +
        theme_minimal(base_size = 14) +
        theme(
          plot.title = element_text(face = "bold"),
          panel.grid.minor = element_blank()
        )
      
      if (input$show_yx) {
        all_vals <- c(df$theo_q, df$sample_q)
        rng <- range(all_vals, na.rm = TRUE)
        pad <- 0.04 * diff(rng)
        lims <- c(rng[1] - pad, rng[2] + pad)
        
        p <- p +
          geom_abline(intercept = 0, slope = 1, color = "#E57200", linetype = "dashed", linewidth = 1.3) +
          coord_cartesian(xlim = lims, ylim = lims)
      }
      
      p
    })
    
    output$dl_qq <- downloadHandler(
      filename = function() { paste0(file_label, ".csv") },
      content = function(file) { write.csv(data.frame(x = dataset), file, row.names = FALSE) }
    )
  })
}


# ==============================================================================
# 5. MAIN UI & SERVER INITIALIZATION
# ==============================================================================
ui <- page_navbar(
  title = "Probability Plots Lab: Poisson-ness & Q-Q Plots",
  theme = bs_theme(version = 5, bootswatch = "flatly"),
  
  tags$head(
    tags$style(HTML("
    /* Force wider borders and larger size on ALL checkboxes in modules and sidebars */
    .checkbox input[type='checkbox'], 
    .form-check-input[type='checkbox'] {
      width: 1.2rem !important;
      height: 1.2rem !important;
      background-color: #ffffff !important;
      border: 2px solid #1e293b !important;
      border-radius: 4px !important;
      cursor: pointer !important;
    }
    
    /* Checked state styling */
    .checkbox input[type='checkbox']:checked, 
    .form-check-input[type='checkbox']:checked {
      background-color: #E57200 !important;
      border-color: #000000 !important;
    }
    
    /* Remove the focus glow completely */
    .checkbox input[type='checkbox']:focus, 
    .form-check-input[type='checkbox']:focus {
      box-shadow: none !important;
      outline: none !important;
      border-color: #1e293b !important; /* Keeps border color steady on click */
    }
    
    /* Text label alignment */
    .checkbox label, 
    .form-check-label {
      font-size: 1.05rem !important;
      padding-left: 0.5rem !important;
      cursor: pointer !important;
    }
  "))
  ),
  
  # Page 1: Poisson-ness Plot
  poissonTabUI("tab_pois"),
  
  # Page 2: Mystery Dataset A (True: Exponential with lambda = 0.4)
  qqMysteryTabUI(
    id = "tab_qq1",
    tab_title = "Question 2: Mystery Dataset A",
    init_dist = "unif",
    u_min_rng = c(-5, 15), u_max_rng = c(1, 25), u_init = c(0, 10), u_step = 0.2,
    n_mu_rng = c(-2, 15), n_mu_init = 5, n_mu_step = 0.1,
    n_var_rng = c(0.5, 40), n_var_init = 12, n_var_step = 0.5,
    e_rate_rng = c(0.05, 2.5), e_rate_init = 1.0, e_rate_step = 0.05
  ),
  
  # Page 3: Mystery Dataset B (True: Normal with mu = 50, sigma^2 = 36)
  qqMysteryTabUI(
    id = "tab_qq2",
    tab_title = "Question 3: Mystery Dataset B",
    init_dist = "unif",
    u_min_rng = c(15, 65), u_max_rng = c(35, 85), u_init = c(35, 65), u_step = 0.5,
    n_mu_rng = c(25, 75), n_mu_init = 40, n_mu_step = 0.5,
    n_var_rng = c(1, 100), n_var_init = 15, n_var_step = 1,
    e_rate_rng = c(0.005, 0.2), e_rate_init = 0.05, e_rate_step = 0.005
  ),
  
  # Page 4: Mystery Dataset C (True: Uniform with a = 10, b = 30)
  qqMysteryTabUI(
    id = "tab_qq3",
    tab_title = "Question 4: Mystery Dataset C",
    init_dist = "norm",
    u_min_rng = c(0, 35), u_max_rng = c(15, 45), u_init = c(5, 35), u_step = 0.5,
    n_mu_rng = c(5, 35), n_mu_init = 20, n_mu_step = 0.5,
    n_var_rng = c(1, 100), n_var_init = 25, n_var_step = 1,
    e_rate_rng = c(0.01, 0.5), e_rate_init = 0.1, e_rate_step = 0.01
  )
)

server <- function(input, output, session) {
  poissonTabServer("tab_pois", dataset = data_pois)
  
  qqMysteryTabServer("tab_qq1", dataset = data_qq_1,
                     u_step = 0.2, n_mu_step = 0.1, n_var_step = 0.5, e_rate_step = 0.05,
                     file_label = "question2_mystery_A")
  
  qqMysteryTabServer("tab_qq2", dataset = data_qq_2,
                     u_step = 0.5, n_mu_step = 0.5, n_var_step = 1, e_rate_step = 0.005,
                     file_label = "question3_mystery_B")
  
  qqMysteryTabServer("tab_qq3", dataset = data_qq_3,
                     u_step = 0.5, n_mu_step = 0.5, n_var_step = 1, e_rate_step = 0.01,
                     file_label = "question4_mystery_C")
}

shinyApp(ui = ui, server = server)
